def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    m = len(ranks)
    bit = [0] * (m + 1)
    result = [0] * len(a)

    for i, value in enumerate(a):
        if i > k:
            pos = ranks[a[i - k - 1]]
            while pos <= m:
                bit[pos] -= 1
                pos += pos & -pos

        rank = ranks[value]
        not_taller = 0
        pos = rank
        while pos:
            not_taller += bit[pos]
            pos -= pos & -pos

        result[i] = min(i, k) - not_taller

        pos = rank
        while pos <= m:
            bit[pos] += 1
            pos += pos & -pos

    return result
